insert into chpms_gaps (seq, kind, finding, source_ids) values
  (1, 'Funding status', 'City ERA has paused at least twice (Aug 6, 2025; Jan 7, 2026); Nov 10, 2026 update reopened it. Expect stop-start availability; confirm before every referral.', 'S002;S003'),
  (2, 'Funding status', 'Milwaukee County could not issue new rent vouchers in 2026 until a $2.5M HOME reallocation (June 2026). Rent-assistance capacity is the binding constraint.', 'S004;S005'),
  (3, 'Voucher access', 'All HCV waiting lists in Milwaukee County (HACM, County, West Allis) are closed; HACM lottery list set June 2026.', 'S006;S016;S020;S021'),
  (4, 'Institutional change', 'SDC (former Community Action Agency) is defunct; UMOS is interim CAA only through June 30, 2027. Watch for the permanent CAA designation.', 'S049'),
  (5, 'Institutional change', 'Coordinated Entry moved from IMPACT to Milwaukee County DHHS in Jan 2026; some public pages (milwaukeecoc.org) are out of date.', 'S011;S014'),
  (6, 'Provider exit', 'Heartland Housing exited 5 Milwaukee PSH buildings (2023); some (Maskani Place) are being redeveloped.', 'S075;S076'),
  (7, 'Population gap', 'Single adults without children have no equivalent to W-2 Emergency Assistance; most flex funds (Family Flex Fund, CCM, Bezos grant) target families.', 'S050;S045;S047'),
  (8, 'Population gap', 'Seniors: providers report senior homelessness as a growing concern; fixed incomes don''t match rents. Few dedicated senior deposit/rent funds were found.', 'S090'),
  (9, 'Population gap', 'Returning citizens: dedicated housing is small (Project RETURN 12 units); voucher disqualifiers (e.g., sex-offender registry) and landlord screening limit options.', 'S063;S006'),
  (10, 'Population gap', 'Veteran rental aid outside SSVF/VASH is thin: VetsNet''s emergency aid is listed for Waukesha, Washington, and Ozaukee counties; VRAP (ARPA) status is unconfirmed.', 'S038;S037'),
  (11, 'Referral vs. money gap', 'Many entries (211, RHRC, ADRC, CVSO, Catholic Charities) are connectors, not funders. The money is concentrated in roughly 8–10 programs.', 'Analysis'),
  (12, 'Landlord opportunity', 'LIFT (damage up to 3x contract rent, vacancy loss) and the Supported Properties Network (sign-on incentive, damage fund) are direct on-ramps for 2nd Chance Housing as a property provider.', 'S007;S008;S046'),
  (13, 'Funding opportunity', 'City CDGA annual RFP (CDBG/HOME/ESG) and HOME-ARP rental housing (reopened Aug 31, 2026); state EHH via the CoC; United Way Safe & Stable Homes annual investments.', 'S001;S070;S044'),
  (14, 'Service opportunity', 'Gaps 2nd Chance Housing could fill: low-barrier units for returning citizens and single adults; units priced for SSI/SSDI incomes; quick-turn units for CE/RRH referrals.', 'Analysis'),
  (15, 'System trend', 'More people are entering Milwaukee homeless services than exiting (MCHH data, 2026). PSH is about 3/4 of homeless beds.', 'S090;S089'),
  (16, 'Deposit gap (confirmed by imported docs)', 'Community Advocates'' deposit help is a guarantee paid back in installments and requires income. MJFLA offers 0% loans; Key to Change pays deposits only for County Housing First clients. No open direct-pay deposit grant for single adults or zero-income households was found.', 'S115;SD3;SD4'),
  (17, 'Reentry momentum', 'The County held a July 28, 2026 landlord event promoting LIFT and reentry programs for renting to returning citizens; a $2M Smart Reentry housing pilot is reported (D1, needs confirmation).', 'S113;S153'),
  (18, 'Data quality', 'Four outside AI-generated documents disagreed on CE lead, CoC lead, Community Advocates status and many phone numbers – see Conflicts_Log; verify by phone before any client referral.', 'SD1;SD2;SD3;SD4');

