insert into chpms_checks (verification_id, record_type, record_id, checked_on, status, method, notes, by_role, from_import)
select v.verification_id, v.record_type, v.record_id, v.checked_on, v.status, v.method, v.notes, 'research', true from (values
  ('VH001', 'org', 'ORG001', '2026-11-11'::date, 'Verified – Current', 'Original research + imported (D1,D2,D3,D4)', 'City ERA direct rental assistance: Jan 7, 2026 pause document vs. Nov 10, 2026 web update saying new applications are accepted — conflicting; web update is newest. | MERGE: Adds Rent Bridge & Security Deposit Guarantee (D2/D3/D4; Needs Confirmation), Autumn West Safe Haven PSH, Project Bridge. REJECTED D4 claim that the live page shows a Jan 7 pause – re-fetched page 2026-11-11 shows Nov 10, 2026 ''will accept new applications''. D1 phone (414) 270-4646 is the former rental-assistance line.'),
  ('VH002', 'org', 'ORG002', '2026-11-11'::date, 'Verified – Current', 'Original research + imported (D1,D3)', 'Walk-in clinic hours conflict on host page (9–4 vs 10–4; referral sheet says 8–4). Collaborative of ~9 partners incl. Community Advocates, IMPACT, Hope House, Legal Action, Legal Aid, Mediate WI, City DNS, Apartment Association of SE WI. | MERGE: hours reported as 9–4 (D3) and 8–4 (D1) – conflict logged.'),
  ('VH003', 'org', 'ORG003', '2026-11-11'::date, 'Verified – Current', 'Original research', 'Milwaukee CoC Lead / Collaborative Applicant; funds ERA (via Community Advocates), CDBG, HOME, HOME-ARP, ESG, HOPWA.'),
  ('VH004', 'org', 'ORG004', '2026-11-11'::date, 'Verified – Current', 'Original research + imported (D1,D3,D4)', 'Coordinated Entry lead agency since Jan 2026. Housing First, TBRA, LIFT, HCV, Street Outreach, My Home. Administrator: James (Jim) Mathy. | MERGE: CE lead assumed Dec 30, 2025 (D4, citing County Legistar – not re-fetched). Smart Reentry Housing Demonstration ($2M federal; D1). My Home: MyHomeProgram@milwaukeecountywi.gov (D3). HCV wait list closed (AASEW 2024 + County page).'),
  ('VH005', 'org', 'ORG005', '2026-11-11'::date, 'Verified – Current', 'Original research + imported (D1,D3,D4)', 'HCV waiting list closed; lottery completed June 2026. Administers HUD-VASH with Milwaukee VA. Address conflict recorded. | MERGE: ~2,000 landlords / 5,800 households (D1); 258 HUD-VASH vouchers (D3/D4, historical news); third address 1419 N 8th St (D3) – conflict logged; PH/PBV lists ''open'' (D3) vs closed (aggregator Jul 2026) – conflict logged.'),
  ('VH006', 'org', 'ORG006', '2026-11-11'::date, 'Verified – Limited', 'Original research + imported (D3)', 'Only other HCV-issuing PHA in Milwaukee County. Operates HCV and VASH; waitlist closed per aggregator (Jul 21, 2026); keeps landlord rental listing. | MERGE: West Allis Office of Housing programs added: Beloit Road Senior Housing (~30% of income; waitlist), down payment/closing cost help, Housing Rehabilitation Grant up to $20,000 (D3).'),
  ('VH007', 'org', 'ORG007', '2026-11-11'::date, 'Unverified Lead', 'Original research', 'Public housing only per aggregator (data last updated June 2024).'),
  ('VH008', 'org', 'ORG008', '2026-11-11'::date, 'Verified – Current', 'Original research + imported (D1,D3,D4)', 'Was Coordinated Entry lead >10 yrs; stepped aside; County became CE lead Jan 2026. 211 remains ''front door'' for housing help. | MERGE: D1 treats IMPACT as Coordinated Entry operator – REJECTED (County is lead since Dec 30, 2025/Jan 2026).'),
  ('VH009', 'org', 'ORG009', '2026-11-11'::date, 'Verified – Current', 'Original research', '100+ members. Leads: CoC Lead = City CDGA; HMIS Lead = Institute for Community Alliances; CE Lead = Milwaukee County DHHS (from Jan 2026; milwaukeecoc.org page still lists United Way/IMPACT — outdated).'),
  ('VH010', 'org', 'ORG010', '2026-11-11'::date, 'Verified – Current', 'Original research', 'Milwaukee CoC HMIS lead; publishes CE training and required referral forms (MKE CEVA, HHTF, CE PSH Referral).'),
